{# ==================== VARIABLES SETUP ==================== #}
{%- set currency = frappe.db.get_value("Company", doc.company, "default_currency") or "EGP" -%}
{%- set cashier_name = frappe.db.get_value("User", {"name": doc.cashier}, "username") or doc.cashier -%}
{%- set cashier_code = frappe.db.get_value("Employee", {"user_id": doc.cashier}, "name") or doc.cashier -%}
{%- set supervisor_name = (frappe.db.get_value("Employee", doc.supervisor_employee, "employee_name") if doc.supervisor_employee else "") -%}
{%- set supervisor_id = doc.supervisor_employee or "" -%}
{# Fallback: if the closing user has no linked Employee, show the user's name / id. #}
{%- if not supervisor_name -%}
    {%- set supervisor_name = frappe.db.get_value("User", doc.modified_by, "full_name") or doc.modified_by or "" -%}
    {%- set supervisor_id = doc.modified_by or "" -%}
{%- endif -%}

{%- set denominations = [
    {"value": 200, "field": "cash_200_egp"},
    {"value": 100, "field": "cash_100_egp"},
    {"value": 50, "field": "cash_50_egp"},
    {"value": 20, "field": "cash_20_egp"},
    {"value": 10, "field": "cash_10_egp"},
    {"value": 5, "field": "cash_5_egp"},
    {"value": 1, "field": "cash_1_egp"}
] -%}

{# Status from the CASH difference #}
{%- set total_diff = doc.difference or 0 -%}
{%- if total_diff == 0 -%}
    {%- set status_class = "status-balanced" -%}
    {%- set status_message = _("BALANCED - Closing Correct") -%}
{%- elif total_diff < 0 -%}
    {%- set status_class = "status-short" -%}
    {%- set status_message = _("SHORT by ") ~ frappe.utils.fmt_money(total_diff | abs, currency=currency) -%}
{%- else -%}
    {%- set status_class = "status-over" -%}
    {%- set status_message = _("OVER by ") ~ frappe.utils.fmt_money(total_diff, currency=currency) -%}
{%- endif -%}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>{{ _("POS Cashier Shift Closing") }}</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; font-size: 10px; line-height: 1.2; color: #333; padding: 10px; max-width: 80mm; margin: 0 auto; }
        .header { text-align: center; border-bottom: 2px solid #333; padding-bottom: 8px; margin-bottom: 12px; }
        .header h1 { font-size: 16px; font-weight: bold; margin-bottom: 4px; text-transform: uppercase; }
        .header .company { font-size: 12px; font-weight: 600; margin-bottom: 2px; }
        .header .pos-profile { font-size: 10px; color: #666; }
        .section { margin-bottom: 10px; padding: 6px; background: #f9f9f9; border-radius: 3px; }
        .section-title { font-size: 11px; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; padding-bottom: 3px; border-bottom: 1px solid #ddd; color: #2c3e50; }
        .info-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 3px 10px; }
        .info-row { display: flex; justify-content: space-between; padding: 2px 0; }
        .info-label { font-weight: 600; color: #555; }
        .info-value { color: #333; text-align: right; }
        table { width: 100%; border-collapse: collapse; margin-top: 5px; }
        thead { background: #34495e; color: white; }
        th { padding: 5px 4px; text-align: left; font-weight: 600; font-size: 9px; text-transform: uppercase; }
        th.text-right, td.text-right { text-align: right; }
        td { padding: 4px; border-bottom: 1px solid #e0e0e0; font-size: 9px; }
        tbody tr:last-child td { border-bottom: 2px solid #34495e; }
        .status-box { padding: 10px; text-align: center; font-size: 13px; font-weight: bold; border-radius: 3px; margin: 10px 0; }
        .status-balanced { background: #d4edda; color: #155724; border: 2px solid #28a745; }
        .status-short { background: #f8d7da; color: #721c24; border: 2px solid #dc3545; }
        .status-over { background: #fff3cd; color: #856404; border: 2px solid #ffc107; }
        .total-highlight { background: #e3f2fd; padding: 5px; border-radius: 3px; margin-top: 5px; font-weight: bold; display: flex; justify-content: space-between; border-left: 3px solid #2196f3; font-size: 10px; }
        .signature-row { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; margin-top: 15px; padding-top: 10px; border-top: 1px solid #ddd; }
        .signature-box { text-align: center; }
        .signature-line { border-top: 1px solid #333; margin-top: 25px; padding-top: 5px; font-weight: 600; font-size: 9px; }
        .footer { margin-top: 10px; padding-top: 8px; border-top: 1px solid #333; text-align: center; font-size: 8px; color: #666; }
        .footer-info { margin: 2px 0; }
    </style>
</head>
<body>
    <div class="header">
        <h1>{{ _("Cashier Shift Closing") }}</h1>
        <div class="company">{{ doc.company }}</div>
        <div class="pos-profile">{{ doc.pos_profile }}</div>
    </div>

    <div class="section">
        <div class="section-title">{{ _("Shift Information") }}</div>
        <div class="info-grid">
            <div class="info-row"><span class="info-label">{{ _("Business Day") }}:</span><span class="info-value">{{ doc.pos_business_day }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Opening Shift") }}:</span><span class="info-value">{{ doc.pos_opening_shift }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Shift Start") }}:</span><span class="info-value">{{ frappe.format_value(doc.shift_start, {"fieldtype": "Datetime"}) }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Shift End") }}:</span><span class="info-value">{{ frappe.format_value(doc.shift_end, {"fieldtype": "Datetime"}) }}</span></div>
        </div>
    </div>

    <div class="section">
        <div class="section-title">{{ _("Cashier Information") }}</div>
        <div class="info-grid">
            <div class="info-row"><span class="info-label">{{ _("Cashier") }}:</span><span class="info-value">{{ cashier_name }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Cashier Code") }}:</span><span class="info-value">{{ cashier_code }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Supervisor") }}:</span><span class="info-value">{{ supervisor_name }}</span></div>
            <div class="info-row"><span class="info-label">{{ _("Supervisor ID") }}:</span><span class="info-value">{{ supervisor_id }}</span></div>
        </div>
    </div>

    <div class="section">
        <div class="section-title">{{ _("Cash Denominations") }} ({{ currency }})</div>
        <table>
            <thead><tr><th>{{ _("Denomination") }}</th><th class="text-right">{{ _("Count") }}</th><th class="text-right">{{ _("Total") }}</th></tr></thead>
            <tbody>
                {% for denom in denominations %}
                {%- set count = doc.get(denom.field) or 0 -%}
                <tr>
                    <td>{{ denom.value }} {{ currency }}</td>
                    <td class="text-right">{{ count }}</td>
                    <td class="text-right">{{ frappe.utils.fmt_money(count * denom.value, currency=currency) }}</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
        <div class="total-highlight">
            <span>{{ _("Actual Counted Cash") }}:</span>
            <span>{{ frappe.utils.fmt_money(doc.actual_counted_cash or 0, currency=currency) }}</span>
        </div>
    </div>

    <div class="section">
        <div class="section-title">{{ _("Cash Reconciliation") }}</div>
        <div class="info-row"><span class="info-label">{{ _("Opening Cash") }}:</span><span>{{ frappe.utils.fmt_money(doc.opening_cash or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("POS Cash Sales") }}:</span><span>{{ frappe.utils.fmt_money(doc.cash_sales or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("Call Center Cash Collected") }}:</span><span>{{ frappe.utils.fmt_money(doc.call_center_cash_collected or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("Cash Refunds") }}:</span><span>- {{ frappe.utils.fmt_money(doc.cash_refunds or 0, currency=currency) }}</span></div>
        <div class="total-highlight"><span>{{ _("Expected Cash") }}:</span><span>{{ frappe.utils.fmt_money(doc.expected_cash or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("Actual Counted Cash") }}:</span><span>{{ frappe.utils.fmt_money(doc.actual_counted_cash or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("Cash Difference") }}:</span><span>{{ frappe.utils.fmt_money(doc.difference or 0, currency=currency) }}</span></div>
    </div>

    <div class="section">
        <div class="section-title">{{ _("Credit / Card Reconciliation") }}</div>
        <div class="info-row"><span class="info-label">{{ _("Expected Credit") }}:</span><span>{{ frappe.utils.fmt_money(doc.expected_credit or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("Actual Credit") }}:</span><span>{{ frappe.utils.fmt_money(doc.actual_credit or 0, currency=currency) }}</span></div>
        <div class="info-row"><span class="info-label">{{ _("Credit Difference") }}:</span><span>{{ frappe.utils.fmt_money(doc.credit_difference or 0, currency=currency) }}</span></div>
    </div>

    {%- if doc.payment_reconciliation -%}
    <div class="section">
        <div class="section-title">{{ _("Modes of Payment") }}</div>
        <table>
            <thead><tr><th>{{ _("Mode") }}</th><th class="text-right">{{ _("Expected") }}</th><th class="text-right">{{ _("Closing") }}</th><th class="text-right">{{ _("Diff") }}</th></tr></thead>
            <tbody>
                {% for p in doc.payment_reconciliation %}
                <tr>
                    <td>{{ p.mode_of_payment }}</td>
                    <td class="text-right">{{ frappe.utils.fmt_money(p.expected_amount or 0, currency=currency) }}</td>
                    <td class="text-right">{{ frappe.utils.fmt_money(p.closing_amount or 0, currency=currency) }}</td>
                    <td class="text-right">{{ frappe.utils.fmt_money(p.difference or 0, currency=currency) }}</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
    {%- endif -%}

    <div class="status-box {{ status_class }}">{{ status_message }}</div>

    {%- if doc.difference_reason -%}
    <div class="status-box">
        <span class="info-label">{{ _("Difference Reason") }}</span><br>
        {{ doc.difference_reason }}
    </div>
    {%- endif -%}

    <div class="signature-section">
        <div class="section-title">{{ _("Signatures") }}</div>
        <div class="signature-row">
            <div class="signature-box"><div class="signature-line">{{ _("Cashier Signature") }}</div></div>
            <div class="signature-box"><div class="signature-line">{{ _("Supervisor Signature") }}</div>{{ supervisor_name }}{% if supervisor_id %} ({{ supervisor_id }}){% endif %}</div>
        </div>
    </div>

    <div class="footer">
        <div class="footer-info">{{ _("Printed on") }}: {{ frappe.utils.now_datetime().strftime("%d-%m-%Y %H:%M:%S") }}</div>
        <div class="footer-info">{{ _("Closing ID") }}: {{ doc.name }}</div>
    </div>
</body>
</html>
